def swim_in_water_binary_search(grid):
    n = len(grid)
    def can_reach(t):
        if grid[0][0] > t:
            return False
        visited = [[False] * n for _ in range(n)]
        stack = [(0, 0)]
        visited[0][0] = True
        while stack:
            r, c = stack.pop()
            if r == n - 1 and c == n - 1:
                return True
            for dr, dc in [(1,0),(-1,0),(0,1),(0,-1)]:
                nr, nc = r + dr, c + dc
                if 0 <= nr < n and 0 <= nc < n and not visited[nr][nc] and grid[nr][nc] <= t:
                    visited[nr][nc] = True
                    stack.append((nr, nc))
        return False
    lo, hi = 0, n * n - 1
    while lo < hi:                                          # binary search on the answer T
        mid = (lo + hi) // 2
        if can_reach(mid):
            hi = mid
        else:
            lo = mid + 1
    return lo

