import java.util.*;

public class Main {
    static int swimInWater(int[][] grid) {
        int n = grid.length;
        boolean[][] visited = new boolean[n][n];
        PriorityQueue<int[]> pq = new PriorityQueue<>((a, b) -> a[0] - b[0]);
        pq.add(new int[]{grid[0][0], 0, 0});
        visited[0][0] = true;
        int ans = 0;
        int[][] dirs = {{1,0},{-1,0},{0,1},{0,-1}};
        while (!pq.isEmpty()) {
            int[] cur = pq.poll();                                    // smallest elevation reachable next
            ans = Math.max(ans, cur[0]);                                // track the max seen so far
            if (cur[1] == n - 1 && cur[2] == n - 1) return ans;
            for (int[] d : dirs) {
                int nr = cur[1] + d[0], nc = cur[2] + d[1];
                if (nr >= 0 && nr < n && nc >= 0 && nc < n && !visited[nr][nc]) {
                    visited[nr][nc] = true;
                    pq.add(new int[]{grid[nr][nc], nr, nc});                  // keyed by its OWN elevation
                }
            }
        }
        return ans;
    }
}

